contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will attempt to call withdraw and withdrawAll as the InvMutTest contract (which is NOT the owner),
    // and assert that such calls revert and that C's balance and depositsCount remain unchanged.
    function run(uint withdrawAmount, uint sendFallbackAmount, bytes calldata callData) public payable {
        require(true);

        // Pre-state observations
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;
        uint beforeOwner = c.owner();

        // If we need to send ether to c to trigger fallback, ensure this contract has the funds.
        if (sendFallbackAmount > 0) {
            require(address(this).balance >= sendFallbackAmount);
            // send ether to c's fallback by calling with empty data
            (bool ok,) = address(c).call{value: sendFallbackAmount}("\x00");
            // fallback will increment depositsCount on success
            // ok may be true even if fallback runs; we don't assert here — we'll observe depositsCount after
        }

        // Try withdraw(uint)
        bool withdrawReverted;
        try c.withdraw(withdrawAmount) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // Try withdrawAll()
        bool withdrawAllReverted;
        try c.withdrawAll() {
            withdrawAllReverted = false;
        } catch {
            withdrawAllReverted = true;
        }

        // Try sendMoney (which uses call) to transfer from C — should revert for non-owner only if call to onlyOwner fails
        bool sendMoneyReverted;
        try c.sendMoney(address(this), 0, callData) {
            sendMoneyReverted = false;
        } catch {
            sendMoneyReverted = true;
        }

        // Post-state observations
        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;
        uint afterOwner = c.owner();

        // The owner must be unchanged by these attempts. Also, if the caller is not owner (this contract),
        // withdraw and withdrawAll must revert and not change c's balance. However, because the InvMutTest
        // contract deployed C, the owner recorded in c is the deployer of C (outside of this function).
        // We assert the general property: if this contract is not the owner, withdraw and withdrawAll revert,
        // and depositsCount only increases if we sent fallback ether successfully earlier.

        // Determine whether this contract is the owner
        bool iamOwner = (beforeOwner == address(this));

        // General rule asserted:
        // - owner is immutable by these calls
        // - if caller is not owner, withdraw and withdrawAll must revert and must not decrease contract balance
        // - depositsCount must have increased exactly by 1 if and only if the fallback call succeeded (detected by afterDeposits > beforeDeposits)
        assert(
            // owner unchanged
            afterOwner == beforeOwner
            // if not owner: both withdraw attempts and sendMoney protected by onlyOwner must have reverted
            && (iamOwner || (withdrawReverted && withdrawAllReverted && sendMoneyReverted))
            // balance never increased except by our earlier fallback send; and if non-owner attempted withdraws they didn't reduce balance
            && (
                // If not owner: balance after >= before (since no successful withdraw by non-owner)
                (iamOwner || afterBalance >= beforeBalance)
            )
            // depositsCount is consistent with observed change (it can only increase by calls to fallback). We don't know if fallback call succeeded,
            // but depositsCount cannot decrease and owner unchanged ensures no other operations ran.
            && (afterDeposits >= beforeDeposits)
        );
    }

    receive() external payable {}
}

