contract InvMutTest {
    C c;
    address deployer;

    constructor(C _c) { c = _c; deployer = msg.sender; }

    // We model a caller (this test contract) that is NOT the owner of c because c was deployed
    // with some other address in the harness. The property: if a non-owner (this contract)
    // tries to invoke withdraw, withdrawAll, or sendMoney, the call must revert and the
    // contract's balance and depositsCount must stay the same.
    function run(address payable target, uint value, bytes memory data, uint depositValue) public payable {
        require(address(this).balance >= depositValue);

        // Record before-values
        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount();

        // Send Ether into c by calling its fallback (only way to increment depositsCount):
        // call low-level to trigger fallback by sending value and empty data
        if (depositValue > 0) {
            // ensure test contract has funds to send
            (bool sent,) = address(c).call{value: depositValue}("");
            // we do not require success: if it fails, balances won't change and that's allowed
        }

        uint midBalance = address(c).balance;
        uint midDeposits = c.depositsCount();

        // Try withdraw as non-owner: should revert
        bool withdrewReverted;
        try c.withdraw(1) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        // Try withdrawAll as non-owner: should revert
        bool withdrawAllReverted;
        try c.withdrawAll() {
            withdrawAllReverted = false;
        } catch {
            withdrawAllReverted = true;
        }

        // Try sendMoney as non-owner: should revert
        bool sendMoneyReverted;
        try c.sendMoney(target, value, data) {
            sendMoneyReverted = false;
        } catch {
            sendMoneyReverted = true;
        }

        // Final observations
        uint afterBalance = address(c).balance;
        uint afterDeposits = c.depositsCount();

        // General rule: if any of the three owner-only calls reverted when invoked by this contract
        // (which is not the owner), then the contract's balance and depositsCount must not have decreased
        // compared to immediately after we optionally sent depositValue into it.
        // We assert that for all inputs: if a non-owner call reverts, the balance and depositsCount are >= mid values.
        assert(
            (withdrewReverted || withdrawAllReverted || sendMoneyReverted) ?
                (afterBalance >= midBalance && afterDeposits >= midDeposits) :
                true
        );
    }

    // Allow receiving Ether to fund this test contract in the harness if needed
    receive() external payable {}
}

