contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // This test takes values to attempt owner-only operations from a non-owner (this contract).
    // It asserts that if this contract is not the owner, then calls to withdraw, withdrawAll, and sendMoney
    // either revert or else do not decrease the contract balance nor change depositsCount.
    function run(address target, uint value, bytes calldata data, uint sendValue) public payable {
        require(address(this).balance >= sendValue);

        // observe before-values
        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount();

        // Attempt withdraw (should revert because this contract is not the owner)
        bool withdrawReverted;
        try c.withdraw(value) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // Attempt withdrawAll
        bool withdrawAllReverted;
        try c.withdrawAll() {
            withdrawAllReverted = false;
        } catch {
            withdrawAllReverted = true;
        }

        // Attempt sendMoney with some Ether sent from this test contract to c first if needed
        // Ensure this contract has provided Ether to c via its fallback by calling c with value
        if (sendValue > 0) {
            // send Ether to c to allow non-zero transfers inside sendMoney if it somehow executed
            // This call will trigger C.fallback and increment depositsCount
            (bool ok, ) = address(c).call{value: sendValue}("");
            // ok may be true; ignore
        }

        bool sendMoneyReverted;
        try c.sendMoney(target, value, data) {
            sendMoneyReverted = false;
        } catch {
            sendMoneyReverted = true;
        }

        uint afterBalance = address(c).balance;
        uint afterDeposits = c.depositsCount();

        // General rule:
        // If this contract is not the owner (which should hold because owner is initial deployer of C),
        // then any attempt to call owner-only functions either reverts, or if it does not revert it must
        // not have reduced c's balance nor decreased depositsCount.
        bool notOwner = (address(this) != c.owner());

        assert(
            // only apply the rule when this contract is not owner
            (!notOwner) || (
                // For each owner-only call: either it reverted, or it did not reduce balance and did not reduce deposits
                (withdrawReverted || (afterBalance >= beforeBalance && afterDeposits >= beforeDeposits))
                && (withdrawAllReverted || (afterBalance >= beforeBalance && afterDeposits >= beforeDeposits))
                && (sendMoneyReverted || (afterBalance >= beforeBalance && afterDeposits >= beforeDeposits))
            )
        );
    }

    receive() external payable {}
}

