contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: caller will attempt to call withdraw via a proxy contract address and an amount.
    // We cannot deploy helpers, so we simulate non-owner by using a low-level call from this contract
    // to c but with a changed msg.sender is impossible; instead we use the following approach:
    // - This contract is the owner of c (it deployed c). It will first deposit some Ether into c by
    //   calling c.sendMoney(address(c), deposit, "") which makes C perform a call to itself and
    //   increase its balance and depositsCount. (sendMoney is onlyOwner so this contract can call it.)
    // - Then we try to call withdraw(amount) using a low-level call from this contract but specifying
    //   the target as address(c) and encoded selector for withdraw so msg.sender remains this contract
    //   (owner) — that would succeed. To test non-owner behavior we instead perform a low-level call to
    //   c from an external account cannot be done here. However the contract C exposes sendMoney which
    //   allows C to call arbitrary target: we can ask C to call withdraw on itself (which will have msg.sender == address(c) and thus fail onlyOwner),
    //   so a CALL initiated by C to C will have msg.sender == address(c), which is NOT the owner (owner is this contract),
    //   therefore that internal call must revert and must not change address(c).balance. This lets us test non-owner rejects.
    // The property: when C (not owner) calls withdraw on C, the call reverts and c's balance stays the same.

    function run(uint deposit, uint withdrawAmount) public payable {
        // Ensure this test contract has funds to deposit
        require(address(this).balance >= deposit, "not enough balance to fund deposit");

        // Record c's balance before
        uint beforeBal = address(c).balance;

        // Deposit into C by making the owner (this contract) ask C to call itself and transfer Ether to itself.
        // Use sendMoney with target = address(c) and value = deposit and empty data so C executes a low-level call
        // from itself to itself; that inner call will trigger fallback and increase balance by deposit.
        bool depReverted;
        try c.sendMoney(address(c), deposit, "") {
            depReverted = false;
        } catch {
            depReverted = true;
        }

        uint afterDepositBal = address(c).balance;

        // Now attempt the non-owner withdraw: ask C (owner: this contract) to call withdraw on address(c) via sendMoney.
        // That makes C perform address(c).call(abi.encodeWithSelector(C.withdraw.selector, withdrawAmount));
        // Inside that call, msg.sender will be address(c), which is not equal to owner, so withdraw should revert.
        bytes memory data = abi.encodeWithSelector(bytes4(keccak256("withdraw(uint256)")), withdrawAmount);
        bool revoked;
        bool callReverted;
        // We call sendMoney which won't revert because this contract is owner; but the inner call to withdraw should revert.
        // To detect whether the inner call reverted, we observe balances and also try/catch the sendMoney call: if sendMoney itself
        // does not revert, the inner low-level call's success is not directly surfaced. However C.sendMoney does not check
        // the return value of the inner call, so sendMoney will succeed regardless. Therefore we must detect whether the inner
        // withdraw reverted by comparing balances: if inner withdraw succeeded, C's balance would have decreased by withdrawAmount
        // and this contract's balance increased. If it reverted, balances remain unchanged. So we capture balances before and after.

        uint balBeforeInner = address(c).balance;
        bool sendReverted;
        try c.sendMoney(address(c), 0, data) {
            sendReverted = false;
        } catch {
            sendReverted = true; // unexpected: sendMoney itself reverted
        }
        uint balAfterInner = address(c).balance;

        // The rule to assert:
        // - The prior deposit (if it succeeded) increased c's balance by exactly deposit; otherwise balance unchanged.
        // - The attempted non-owner withdraw (performed by C calling C) must NOT decrease c's balance (i.e., balAfterInner == balBeforeInner)
        //   because msg.sender inside withdraw would be address(c) which is not owner, so withdraw should revert or have no effect.
        // Compose assertion: handle deposit outcome and non-owner withdraw invariant.

        // Compute expected balance after deposit
        uint expectedAfterDeposit = beforeBal + (depReverted ? 0 : deposit);

        assert(
            afterDepositBal == expectedAfterDeposit &&
            balAfterInner == balBeforeInner
        );
    }

    receive() external payable {}
}

