        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount();

        // Attempt withdraw as a top-level try/catch
        bool reverted;
        try c.withdraw(withdrawAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe state after withdraw
        uint afterBalance = address(c).balance;
        uint afterDeposits = c.depositsCount();

        // Determine whether this test contract is owner
        bool amOwner = (c.owner() == address(this));

        // Assert general invariant: if not owner then withdraw reverted and no state change
        assert(amOwner || (reverted && afterBalance == beforeBalance && afterDeposits == beforeDeposits));
    }

