}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We accept parameters to drive different calls: kind selects which function to call on C;
    // value is the Ether amount to send with the call (if applicable);
    // target and data are for sendMoney. We also provide an amountToSendToC to trigger fallback by sending Ether to C.
    function run(uint8 kind, uint value, address target, bytes calldata data, uint amountToSendToC) public payable {
        require(kind <= 3);
        // If we will send Ether from this contract to C (to trigger fallback), ensure we have enough balance
        if (amountToSendToC > 0) {
            require(address(this).balance >= amountToSendToC);
            // send Ether to C without data to trigger fallback
            (bool ok, ) = address(c).call{value: amountToSendToC}("");
            // the call may succeed or fail (but fallback increments depositsCount only on successful reception)
        }

        // record observables before the call
        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount();

        bool reverted;
        // perform one of the owner-only functions from this contract (InvMutTest is the deployer of C so it's owner)
        if (kind == 0) {
            // withdrawAll
            try c.withdrawAll() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else if (kind == 1) {
            // withdraw(amount)
            try c.withdraw(value) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else if (kind == 2) {
            // sendMoney(target, value, data)
            try c.sendMoney(target, value, data) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // call fallback by sending value with empty data directly via c (from this contract)
            if (value > 0) require(address(this).balance >= value);
            // use low-level call to forward Ether and no data to trigger fallback
            (bool ok, ) = address(c).call{value: value}("");
            // consider this as reverted == !ok
            reverted = !ok;
        }

        // observables after
        uint afterBalance = address(c).balance;
        uint afterDeposits = c.depositsCount();

        // General rule asserted:
        // - If one of the owner-executed functions (withdrawAll, withdraw, sendMoney) did NOT revert, then C's balance must be <= beforeBalance (it cannot increase), and it decreases by at most the requested value (for withdraw and sendMoney) — for withdrawAll the decrease is <= beforeBalance.
        // - If we invoked the fallback by sending empty calldata (kind==3) or via amountToSendToC earlier, then depositsCount increases iff Ether was actually accepted by C (i.e., afterBalance > beforeBalance implies afterDeposits == beforeDeposits + 1).

        assert(
            // Part A: owner-invoked functions don't increase balance when they succeed
            ((kind == 0 || kind == 1 || kind == 2) && !reverted) ? (afterBalance <= beforeBalance) : true
            // and specifically, for withdraw(value) and sendMoney(target,value,..) the decrease is at most value when succeeded
            && ((kind == 1 || kind == 2) && !reverted ? (beforeBalance - afterBalance <= value) : true)
            // for withdrawAll, decrease is at most beforeBalance (tautologically true but kept for clarity)
            && (kind == 0 && !reverted ? (beforeBalance - afterBalance <= beforeBalance) : true)
            // Part B: fallback deposit correlation: if balance increased then depositsCount increased by exactly the amount of successful empty-call fallback receipts (we can only observe +1 per successful empty calldata call here)
            && ( (afterBalance > beforeBalance) ? (afterDeposits == beforeDeposits + ( (amountToSendToC > 0 ? 1 : 0) + (kind == 3 && value > 0 ? 1 : 0) )) : (afterDeposits >= beforeDeposits) )
        );
    }

    // allow this test contract to receive Ether when C pays out
    receive() external payable {}
}

