contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // This test checks that when this contract (which is NOT the original deployer of C)
    // sends ETH to C via the plain call, c.depositsCount increments and C's balance increases,
    // but attempting to call withdraw or sendMoney from this contract must revert (i.e., must not
    // be allowed to make C send Ether out). We assert that either withdraw/sendMoney revert,
    // or if they don't, then C's balance did not decrease (i.e., no Ether left C).

    function run(uint sendAmount, address target, uint callValue, bytes calldata data) public payable {
        require(address(this).balance >= sendAmount, "not enough balance for send");
        // record initial observations
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // send ETH to C so fallback triggers (this increments depositsCount)
        // Use a low-level call via c with value: sendAmount
        // Must be a top-level statement
        (bool successSend,) = address(c).call{value: sendAmount}("");
        // record after sending
        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;

        // Now attempt to call withdraw(uint) from this contract; it should revert because onlyOwner
        bool withdrewReverted;
        try c.withdraw(callValue) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        // Attempt to call sendMoney — should also revert when called by non-owner
        bool sendMoneyReverted;
        try c.sendMoney(target, callValue, data) {
            sendMoneyReverted = false;
        } catch {
            sendMoneyReverted = true;
        }

        // Final observed balance
        uint finalBalance = address(c).balance;

        // General rule asserted:
        // 1) The plain ETH transfer to c increased depositsCount by either 1 (fallback called) or 0 if transfer failed.
        // 2) If withdraw or sendMoney did not revert (unexpected), they must not have decreased C's balance (safety).
        // Combine into single assert over observed values and revert flags.
        assert(
            // depositsCount changed by at most +1 and only non-negative
            (afterDeposits == beforeDeposits || afterDeposits == beforeDeposits + 1)
            &&
            // balance after the direct send equals previous plus sendAmount if the send succeeded, otherwise unchanged
            ((successSend && afterBalance == beforeBalance + sendAmount) || (!successSend && afterBalance == beforeBalance))
            &&
            // If withdraw/sendMoney reverted, no further constraint; if they did NOT revert (which would violate onlyOwner), C's final balance must be >= balance after those calls
            ((withdrewReverted && sendMoneyReverted) || (finalBalance >= afterBalance))
        );
    }

    // accept ETH for this contract when performing tests
    receive() external payable {}
}

