            require(ok, "deposit call failed");
        }

        uint afterDepositCBalance = address(c).balance;
        uint afterDeposit = c.depositsCount();

        // owner withdraws some amount (bounded by contract balance)
        uint toWithdraw = withdrawAmount;
        if (toWithdraw > afterDepositCBalance) {
            toWithdraw = afterDepositCBalance;
        }

        // perform withdraw
        c.withdraw(toWithdraw);

        uint afterWithdrawCBalance = address(c).balance;
        uint afterWithdrawThis = address(this).balance;

        // perform sendMoney: as owner this contract may call arbitrary target with value and data
        // cap sendValue to current contract balance
        uint toSend = sendValue;
        if (toSend > afterWithdrawCBalance) {
            toSend = afterWithdrawCBalance;
        }
        c.sendMoney(target, toSend, data);

        uint finalCBalance = address(c).balance;
        uint finalThis = address(this).balance;

        // General rule asserted:
        // 1) depositsCount increased by exactly 1 if and only if depositAmount > 0 (fallback increments once per fallback call)
        // 2) withdraw reduced c balance by toWithdraw and increased this contract balance by toWithdraw
        // 3) final c balance equals initial + depositAmount - toWithdraw - toSend
        assert(
            // depositsCount behavior
            (afterDeposit == beforeDeposits + (depositAmount > 0 ? 1 : 0))
            // withdraw effect
            && (afterWithdrawCBalance + toWithdraw == afterDepositCBalance)
            && (afterWithdrawThis == afterThis + toWithdraw)
            // overall balance conservation for c across operations
            && (finalCBalance + toSend + toWithdraw == beforeCBalance + depositAmount)
        );
    }

    receive() external payable {}
}

