contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // The test takes an amount and arbitrary call data to try withdraw/send; it is payable
    function run(uint sendAmount, uint withdrawAmount, address target, bytes calldata data) public payable {
        require(address(this).balance >= sendAmount, "insufficient balance to fund call");

        // Record observable before-values
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;
        uint beforeMyBalance = address(this).balance;

        // 1) Try to trigger fallback by sending Ether to c (this will increment depositsCount if fallback executed)
        bool fallbackReverted;
        (bool ok1,) = address(c).call{value: sendAmount}("");
        fallbackReverted = !ok1;

        // 2) Attempt withdrawAll as non-owner (this contract is NOT the owner)
        bool withdrawAllReverted;
        try c.withdrawAll() {
            withdrawAllReverted = false;
        } catch {
            withdrawAllReverted = true;
        }

        // 3) Attempt withdraw specific amount as non-owner
        bool withdrawReverted;
        try c.withdraw(withdrawAmount) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // 4) Attempt sendMoney (which performs a low-level call) as non-owner
        bool sendMoneyReverted;
        try c.sendMoney(target, withdrawAmount, data) {
            sendMoneyReverted = false;
        } catch {
            sendMoneyReverted = true;
        }

        // Read after-values
        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;
        uint afterMyBalance = address(this).balance;

        // General rule asserted for all inputs:
        // - withdrawAll and withdraw and sendMoney must revert when called by this contract (not owner),
        //   and if they revert then they must not have changed c's balance or depositsCount.
        // - The only allowed change to depositsCount is via a successful fallback call (i.e., when the low-level
        //   value-send succeeded). If the low-level value-send failed, depositsCount must be unchanged.
        assert(
            // Non-ownership: at least one of the three management calls reverts (we expect all to revert),
            // but to make this a provable general rule: if any of these management calls did NOT revert,
            // then it must not have changed balance or depositsCount either. Conversely, if they did revert,
            // state must be unchanged. We express: if a call reverted OR did not revert, state must remain consistent.

            // For withdrawAll and withdraw: if they reverted then balances unchanged; if not reverted then also balances unchanged
            // (this forces that non-owner cannot extract funds — in correct contract they revert, so state unchanged)
            (withdrawAllReverted ? (afterBalance == beforeBalance && afterDeposits == beforeDeposits) : (afterBalance == beforeBalance && afterDeposits == beforeDeposits))
            && (withdrawReverted ? (afterBalance == beforeBalance && afterDeposits == beforeDeposits) : (afterBalance == beforeBalance && afterDeposits == beforeDeposits))
            && (sendMoneyReverted ? (afterBalance == beforeBalance && afterDeposits == beforeDeposits) : (afterBalance == beforeBalance && afterDeposits == beforeDeposits))
            // For the explicit low-level call that tried to send Ether to fallback: if it failed, depositsCount unchanged; if it succeeded, depositsCount increased by exactly 1
            && (fallbackReverted ? (afterDeposits == beforeDeposits && afterBalance == beforeBalance && afterMyBalance + sendAmount == beforeMyBalance) : (afterDeposits == beforeDeposits + 1 && afterBalance == beforeBalance + sendAmount && afterMyBalance + sendAmount == beforeMyBalance))
        );
    }

    receive() external payable {}
}

