    constructor(C _c) { c = _c; }

    // single public test function: simulate calling c's fallback by sending Ether to it
    function run(address target, uint amount) public payable {
        require(address(this).balance >= amount);
        // read before-values
        uint beforeCount = c.depositsCount();
        uint beforeBal = address(c).balance;

        // perform the call that should trigger fallback: send `amount` wei to c
        // using low-level call on the contract address so fallback() executes
        (bool ok, ) = address(c).call{value: amount}("\x00");
        // we accept either success or failure, but the observable effects differ

        uint afterCount = c.depositsCount();
        uint afterBal = address(c).balance;

        // General rule: if the low-level call succeeded, then depositsCount increases by 1
        // and contract balance increases by exactly `amount`. If it failed, neither changes.
        assert((ok && afterCount == beforeCount + 1 && afterBal == beforeBal + amount)
               || (!ok && afterCount == beforeCount && afterBal == beforeBal));
    }

    // receive to allow this test contract to hold Ether when deployed/run
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    // params: target address to forward to, value to send, and arbitrary data
    function run(address target, uint value, bytes calldata data) public payable {
        require(address(this).balance >= value);

        // read before-values (allowed: public getters and address balances)
        uint beforeCount = c.depositsCount();
        uint beforeBal = address(c).balance;
        uint beforeThis = address(this).balance;

        // perform the state-changing call on c: sendMoney is public and may transfer out of c
        bool reverted;
        try c.sendMoney(target, value, data) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-values
        uint afterCount = c.depositsCount();
        uint afterBal = address(c).balance;
        uint afterThis = address(this).balance;

        // General rule:
        // 1) depositsCount never decreases.
        // 2) If the call reverted, balances are unchanged.
        // 3) If the call succeeded, C's balance decreased by at most `value` (could be less if target did not accept full amount),
        //    and the test contract's balance did not increase as a result of that transfer (since C pays out, not this contract).
        assert(
            // depositsCount monotonic non-decrease
            afterCount >= beforeCount
            && (
                // if reverted: no balance changes
                (reverted && afterBal == beforeBal && afterThis == beforeThis)
                ||
                // if succeeded: c's balance decreased by at most value, this contract's balance did not increase due to c
                (!reverted && beforeBal >= afterBal && beforeBal - afterBal <= value && afterThis == beforeThis)
            )
        );
    }

    receive() external payable {}
}
